<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\WebAuthn\Infrastructure\Driven;

use DateTimeImmutable;
use Override;
use PDO;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnChallenge;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnChallengeGateway;

final class WebAuthnChallengeSqlAdapter implements WebAuthnChallengeGateway
{
    public function __construct(private readonly PDO $pdo)
    {
        $this->purgeExpired();
    }

    #[Override]
    public function store(WebAuthnChallenge $challenge): void
    {
        $stmt = $this->pdo->prepare(
            'INSERT INTO _oauth_webauthn_challenge
             (challenge_id, tenant_id, user_uid, challenge, type, options_json, created_at, expires_at,
              verified, verified_at, verified_user_uid, verified_username)
             VALUES
             (:challenge_id, :tenant_id, :user_uid, :challenge, :type, :options_json, :created_at, :expires_at,
              :verified, :verified_at, :verified_user_uid, :verified_username)'
        );
        $stmt->bindValue('challenge_id', $challenge->challengeId);
        $stmt->bindValue('tenant_id', $challenge->tenantId);
        $stmt->bindValue('user_uid', $challenge->userUid);
        $stmt->bindValue('challenge', $challenge->challenge);
        $stmt->bindValue('type', $challenge->type);
        $stmt->bindValue('options_json', $challenge->optionsJson);
        $stmt->bindValue('created_at', $challenge->createdAt->format('Y-m-d H:i:s'));
        $stmt->bindValue('expires_at', $challenge->expiresAt->format('Y-m-d H:i:s'));
        $stmt->bindValue('verified', $challenge->verified ? 1 : 0, PDO::PARAM_INT);
        $stmt->bindValue('verified_at', $challenge->verifiedAt?->format('Y-m-d H:i:s'));
        $stmt->bindValue('verified_user_uid', $challenge->verifiedUserUid);
        $stmt->bindValue('verified_username', $challenge->verifiedUsername);
        $stmt->execute();
    }

    #[Override]
    public function findById(string $challengeId, string $tenantId): ?WebAuthnChallenge
    {
        $stmt = $this->pdo->prepare(
            'SELECT * FROM _oauth_webauthn_challenge
             WHERE challenge_id = :challenge_id AND tenant_id = :tenant_id'
        );
        $stmt->bindValue('challenge_id', $challengeId);
        $stmt->bindValue('tenant_id', $tenantId);
        $stmt->execute();
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        return $row ? $this->mapRow($row) : null;
    }

    #[Override]
    public function markVerified(WebAuthnChallenge $challenge): void
    {
        $stmt = $this->pdo->prepare(
            'UPDATE _oauth_webauthn_challenge
             SET verified = 1, verified_at = :verified_at,
                 verified_user_uid = :verified_user_uid, verified_username = :verified_username
             WHERE challenge_id = :challenge_id AND tenant_id = :tenant_id'
        );
        $stmt->bindValue('verified_at', $challenge->verifiedAt?->format('Y-m-d H:i:s'));
        $stmt->bindValue('verified_user_uid', $challenge->verifiedUserUid);
        $stmt->bindValue('verified_username', $challenge->verifiedUsername);
        $stmt->bindValue('challenge_id', $challenge->challengeId);
        $stmt->bindValue('tenant_id', $challenge->tenantId);
        $stmt->execute();
    }

    #[Override]
    public function purgeExpired(): void
    {
        $stmt = $this->pdo->prepare(
            'DELETE FROM _oauth_webauthn_challenge WHERE expires_at < :now'
        );
        $stmt->bindValue('now', (new DateTimeImmutable())->format('Y-m-d H:i:s'));
        $stmt->execute();
    }

    private function mapRow(array $row): WebAuthnChallenge
    {
        return new WebAuthnChallenge(
            challengeId: $row['challenge_id'],
            tenantId: $row['tenant_id'],
            userUid: $row['user_uid'] ?? null,
            challenge: $row['challenge'],
            type: $row['type'],
            optionsJson: $row['options_json'] ?? null,
            createdAt: new DateTimeImmutable($row['created_at']),
            expiresAt: new DateTimeImmutable($row['expires_at']),
            verified: (bool) ($row['verified'] ?? false),
            verifiedAt: !empty($row['verified_at']) ? new DateTimeImmutable($row['verified_at']) : null,
            verifiedUserUid: $row['verified_user_uid'] ?? null,
            verifiedUsername: $row['verified_username'] ?? null,
        );
    }
}
